package com.example.starter.enums;

/**
 * Topic 离线保留策略。
 */
public enum RetentionStrategy {
    /** 离线时新消息直接丢弃。 */
    DROP,
    /** 离线时只保留最新一条，旧消息被覆盖。 */
    LATEST,
    /** 离线时完整顺序保留。 */
    FIFO,
    /** 离线时最多保留 bound 条，超出后驱逐最旧消息。 */
    BOUNDED
}

package com.example.starter.enums;

/**
 * 设备消息在本地转发队列中的生命周期状态。
 */
public enum MessageStatus {
    /** 已持久化、等待投递。 */
    PENDING,
    /** 已投递给上游适配器、等待明确 ACK。 */
    INFLIGHT,
    /** 已收到明确 ACK，转发完成。 */
    FORWARDED
}

package com.example.starter.enums;

/**
 * 审计事件类型。
 */
public enum AuditEventType {
    /** DROP 策略离线丢弃。 */
    DROP_POLICY,
    /** LATEST 策略覆盖旧消息。 */
    OVERWRITE_LATEST,
    /** BOUNDED 策略因条数上限驱逐最旧消息。 */
    EVICT_BOUNDED,
    /** 总容量不足，驱逐最低优先级中最旧的非 in-flight 消息。 */
    EVICT_CAPACITY,
    /** 驱逐后仍无法写入，拒绝新消息。 */
    REJECT_CAPACITY
}

